mapper.select:
SELECT nc.id, nc.notice_id, nc.content, nc.reg_user_id, nc.reg_date, nc.mod_date, nc.del_yn, u.user_name
FROM notice_comment nc
INNER JOIN user u
ON nc.reg_user_id = u.id
WHERE nc.notice_id = #{id}
AND nc.del_yn = 'N';

mapper.update:
UPDATE notice_comment SET
content = #{content}
WHERE id = #{id}

UPDATE notice_comment SET
del_yn = 'Y'
WHERE id = #{id}
